window.GAME_TR = window.GAME_TR || [];
window.GAME_TR.push({
  unit: 7,
  en: {
    "u.realm": "Microbe Marsh",
    "u.story": "The Greenwood Laboratory has a marshy corner where fallen leaves vanish after only a few months, while the grass around it grows unusually green. The culprits are living things so small that you can only see them with a microscope! Take your magnifying glass, Petri dishes and notebook, and follow the flow of energy from the Sun through plants and animals to nature's mysterious 'clean-up workers'.",
    "s.7.3.learn": ["The food chains and webs in the previous topic had no microorganisms, but microorganisms are everywhere.","Each spot on a spoiled apple is millions of cells of microscopic fungi; this kind of fungus is called **mould**.","Microorganisms make things **decay**; organisms that make things decay are **decomposers**.","Any substance made by a living organism (a plant or an animal) is called **organic matter**.","Some microorganisms break down organic matter when they feed on it, making the apple **rot**.","Activity 7.3.1: what can microorganisms decay?","Decay by microorganisms can be useful or not useful.","Investigating how temperature affects the decay of bread: purpose and equipment.","The steps: two pieces of bread, add water, leave in the air, cover, one in a warm place – one in a refrigerator.","Bread mould shows up as patches; through a microscope it is made of tiny threads.","Your conclusion must come from your actual results, not from what you thought should happen.","Plan your own experiment to test a hypothesis about how moisture (water) affects decay."],
    "s.7.3.learnDetail.0": ["Microorganisms live in the air, in the soil, in water, on our skin and inside our bodies.","The apple in the book's picture has microorganisms growing on its surface.","The book asks (Getting started): in a group of three, think of three different ways to complete the sentence 'A microorganism is …'."],
    "s.7.3.learnDetail.1": ["The apple is mouldy.","The spots on the apple are colonies of fungi."],
    "s.7.3.learnDetail.2": ["The microorganisms have changed the apple: they have made it decay.","Many kinds of microorganism are decomposers, including some kinds of bacteria and microscopic fungi."],
    "s.7.3.learnDetail.3": ["Apples come from plants, which are living organisms, so apples are organic matter.","Organic matter can be made by a plant or by an animal."],
    "s.7.3.learnDetail.4": ["The microscopic fungi have broken down the crisp, fresh apple and made it become brown and soft.","This is what has caused the apple to decay."],
    "s.7.3.learnDetail.5": ["First think quietly on your own; when your teacher tells you, discuss with your partner; be ready to share with the class.","Question 1: which of these are made of organic matter – bread, water, leather, rock, wood, fruit?","Question 2: think of two more things made of organic matter and two that are not. Question 3: which things in your answers can be broken down by microorganisms?"],
    "s.7.3.learnDetail.6": ["The book asks: some microorganisms are decomposers – explain what this means.","The book asks: describe one way in which decay by microorganisms is not useful, and suggest one way in which it is useful."],
    "s.7.3.learnDetail.7": ["This investigation gives you practice in carefully collecting results and using them to make a conclusion.","You need: 2 similar pieces of bread, 2 paper plates, 2 plastic bags or some transparent food wrap, a dropper pipette."],
    "s.7.3.learnDetail.8": ["Step 1: put two similar pieces of bread onto two paper plates.","Step 2: add a little water to both pieces; take care not to get them too wet.","Step 3: leave the bread open to the air for about 30 minutes, then cover each plate with a plastic bag or food wrap.","Step 4: put one plate in a warm place and the other in a refrigerator. Step 5: record the appearance of each piece of bread each day, for several days."],
    "s.7.3.learnDetail.9": ["The bread in the book's photo has several patches of blue mould growing on it.","Through a microscope, bread mould is made of tiny threads.","The book asks: compare the results for the bread in the warm place and in the cold place; did others in your class get similar results, and if not, why; make a conclusion."],
    "s.7.3.learnDetail.10": ["Self-assessment (very well / fairly well / not at all): I was careful to add the same amount of water to each piece of bread.","I made a careful record of the appearance of each piece each day, and wrote or drew my results clearly so someone else could understand them.","I made my conclusion from my actual results, not from what I thought should happen.","Write down one thing you did really well, and one thing you could do better next time and how."],
    "s.7.3.learnDetail.11": ["You can use ideas from the temperature investigation. The hypothesis to test: 'Moist bread decays more quickly than dry bread.'","Think about: the variable you will change and how; the variable you will observe or measure and how.","Think about: the variables you will keep the same; the results you predict if the hypothesis is correct.","If you can, do the experiment, collect results and use them to make a conclusion."],
    "s.7.3.extend": ["This experiment usually shows the bread in the warm place going mouldy faster: microorganisms grow faster when it is warm. A refrigerator only slows them down; it does not kill them.","Mould grows from tiny spores floating in the air; the tiny black dots on bread mould contain spores.","The humid spring season in northern Vietnam (about February–April) is both damp and warm, so clothes, bread and walls go mouldy easily. Drying, salting or chilling food makes it last longer.","Do not cut off the mouldy part and eat the rest of the bread: the fungal threads may have spread deep inside, and some moulds make poisons."],
    "s.7.3.figcap": ["Microorganisms are everywhere","Decomposers feed on the apple and break it down: the apple goes mouldy and then rots","How to recognise organic matter, and what microorganisms do to it","Five steps of the investigation of how temperature affects decay","Bread mould seen with the eye and through a microscope","The variables in the temperature investigation: only one variable is changed","A planning frame to test the hypothesis about moisture"],
    "s.7.1.learn": ["A **microorganism** is a living organism so small that you can only see it clearly with a microscope.","There are several kinds of microorganism: **bacteria**, microscopic **fungi**, **protozoa** and **algae**.","Bacteria are everywhere; each bacterium is just one cell, much smaller than animal or plant cells.","Fungi are not always microorganisms: **mushrooms** and **toadstools** are large and easy to see.","Some fungi are made only of single cells, so they are definitely microorganisms – for example **yeast**.","A single cell of a bacterium or fungus divides repeatedly to make a **colony**, big enough to see with your eyes.","Microorganisms are grown safely in a **Petri dish** containing **agar jelly**; the dish and jelly must be **sterile**.","Experiment 'Growing microorganisms from the air': get the equipment and read the safety notes first.","The steps: open the lid, put it back and tape it, turn the dish over, label it, leave it for a few days.","After a few days you see colonies of bacteria and fungi; each colony began as one microorganism.","Pond water contains algae (plant-like) and protozoa (animal-like)."],
    "s.7.1.learnDetail.0": ["Like all living organisms, microorganisms are made of cells.","Many microorganisms are made of only one cell: they are **single-celled**.","The book asks (Getting started): name two diseases caused by bacteria in humans, and what other kinds of organisms can cause disease."],
    "s.7.1.learnDetail.1": ["Each kind is described later in the topic.","The word 'microscopic' matters: only very small fungi are microorganisms."],
    "s.7.1.learnDetail.2": ["'Bacteria' is plural; one of them is a 'bacterium'.","You could fit about 1000 of the bacteria shown in the book, lined up end to end, between two millimetre marks on your ruler – that is, in 1 mm.","Most bacteria are harmless; only a few kinds can make you ill.","Example: the bacteria that live in our digestive systems are completely harmless."],
    "s.7.1.learnDetail.3": ["'Fungi' is plural; the singular is 'fungus'.","Mushrooms and toadstools are only part of the fungus's body, and they only grow at certain times of year.","Most of the time the fungus is just a tangle of very thin threads, often growing under the ground or inside a dead log.","The threads are so thin that they are difficult to see without a microscope."],
    "s.7.1.learnDetail.4": ["These fungi do not produce mushrooms or toadstools, and they are made of single cells, not threads.","The white 'powder' sometimes seen on grapes is millions of cells of yeast – a microscopic fungus; the cells feed on sugar in the grapes.","Through a microscope you can see little buds growing out of some cells: this is how yeast reproduces.","The book asks: viruses are even smaller than bacteria – why are they not usually called microorganisms? We can see yeast on fruit – why is yeast still classed as a microorganism?"],
    "s.7.1.learnDetail.5": ["A single microorganism is too small to see without a microscope.","When left to grow, that cell divides again and again to make a collection of many cells.","This collection of cells is called a colony; it is big enough to see without a microscope."],
    "s.7.1.learnDetail.6": ["This can be done safely in the laboratory.","Agar jelly is a special kind of jelly in the Petri dish; it contains nutrients for the microorganisms.","Sterile means that any living organisms on the dish and jelly have been killed.","The book asks: suggest what the word 'nutrients' means (more in Topic 7.4), and why the dish and jelly must be sterile."],
    "s.7.1.learnDetail.7": ["Microorganisms are so small that they float around in the air; you cannot see them, but they are there. The experiment uses agar jelly to grow bacteria and fungi from the air.","You need: a sterile Petri dish containing sterile agar jelly, some sticky tape, a pen that can write on plastic.","Safety: do not breathe or talk over the top of the jelly – you do not want to grow bacteria from your breath.","The bacteria and fungi you grow are very unlikely to be harmful, but just in case keep the lid on after step 2, so you cannot accidentally touch them or breathe them in."],
    "s.7.1.learnDetail.8": ["Step 1: take the lid off and leave the dish open for about 5–10 minutes so microorganisms in the air get onto the jelly.","Step 2: put the lid back and fasten it onto the dish with sticky tape.","Step 3: turn the dish upside down, so droplets of water that form inside do not make puddles on the jelly – puddles might drown the microorganisms.","Step 4: label the bottom of the dish with your name and the date. Step 5: leave the dish in a safe place for a few days; do not take the lid off."],
    "s.7.1.learnDetail.9": ["Step 6: after a few days, look at the jelly: you will see colonies of bacteria and fungi growing on it.","Colonies of bacteria usually have smooth edges; colonies of fungi are usually furry or have rough edges.","The book asks you to draw the colonies on the jelly and label which are bacteria and which are fungi."],
    "s.7.1.learnDetail.10": ["Pond water seen through a microscope contains many tiny living organisms.","Algae are tiny plant-like organisms (singular: alga); protozoa are animal-like organisms (singular: protozoan).","Some of the microorganisms in a drop of pond water are not single-celled. The book asks: how are their cells arranged?","The book asks you to draw one microorganism with cells like animal cells and one with cells like plant cells, and label the differences."],
    "s.7.1.extend": ["Viruses are even smaller than bacteria, but they are not made of cells and can only reproduce inside other living cells, so they are not usually counted as microorganisms.","Algae are plant-like because their cells have chloroplasts and photosynthesise; protozoa (for example Paramecium) must eat ready-made food, like animals.","In Vietnam, useful microorganisms are right in the kitchen: yeast makes bread rise and is used to make rice wine; lactic acid bacteria make yoghurt and pickled mustard greens.","A few microorganisms cause disease: bacteria cause cholera and typhoid; a protozoan causes malaria (spread by mosquitoes)."],
    "s.7.1.figcap": ["Four kinds of microorganism seen through a microscope","Bacteria are much smaller than plant and animal cells: about 1000 bacteria end to end measure only 1 mm","The mushroom is only the small part you see; most of the fungus is a tangle of very thin threads underground","The white powder on grapes is millions of yeast cells; yeast reproduces by budding","One cell divides again and again into a colony you can see with your eyes","Six steps to grow microorganisms from the air","Telling colonies apart: bacteria (smooth edges) and fungi (furry or rough edges)"],
    "s.7.4.learn": ["Decay can be harmful: the microorganisms that make an apple rot have spoiled the food; but most of the time decay is useful.","Microorganisms break down dead bodies and animal waste; fungi and bacteria are the most important decomposers.","Without decomposers there would be heaps of dead plants, dead animals and animal **dung** everywhere.","Dead bodies and waste contain **nutrients**; decomposers return them to the soil so plants can grow.","Activity 7.4.1: watch a piece of fruit decay in a warm place.","Decomposers feed on dead bodies and waste: energy from these is transferred to the decomposers.","Decomposers can be added to a food chain or web with arrows from every organism to them.","A toadstool on a log is not a microorganism, but the part of the fungus inside the log is breaking it down.","Most microorganisms are harmless, but malaria is caused by a microscopic protozoan and spread by mosquitoes.","DDT does not break down completely in an animal's body, so it passes along food chains and harms animals.","DDT makes the egg shells of birds of prey very thin; after DDT was banned in 1972, numbers of young birds rose again.","Malaria facts and other ways of controlling malaria apart from DDT."],
    "s.7.4.learnDetail.0": ["No-one would want to eat a rotten apple.","The book asks (Getting started): the arrows in a food chain show the direction energy flows from one organism to another – correct or not? 'All animals are consumers and all plants are producers' – correct or not? 'Some consumers are herbivores and some are carnivores' – correct or not?"],
    "s.7.4.learnDetail.1": ["Microorganisms decompose dead bodies and animal waste.","Almost all decomposers are microorganisms.","Example in the book's photo: a fungus is a decomposer breaking down elephant dung."],
    "s.7.4.learnDetail.2": ["If dead bodies and waste are not broken down by decomposers, they just build up.","The opening photo of the topic shows a dung beetle rolling a ball of dung."],
    "s.7.4.learnDetail.3": ["Nutrients are substances that living organisms can use to supply them with energy or to help them grow – this is the even more important reason why decomposers are useful.","When microorganisms decay organic matter, they return the nutrients to the soil; plants use them to help them grow – really helpful for the plants.","This also helps animals, because there are more plants to eat."],
    "s.7.4.learnDetail.4": ["You need: a piece of fruit (such as a lemon or strawberry), a plate or dish to put it on, a pen to write on the plate.","Step 1: write your name on the dish, put the fruit on it, do not cover the fruit. Step 2: leave it in the laboratory or another warm place.","Step 3: look at the fruit every two or three days; take photographs or make drawings.","The book asks: what changes can you see in the fruit? Explain what happens to it. A photo of mouldy oranges asks: what sort of decomposers are growing on them?"],
    "s.7.4.learnDetail.5": ["Decomposers feed on almost every organism after it dies, and also on waste from animals.","This is how decay microorganisms get their energy."],
    "s.7.4.learnDetail.6": ["You do not usually do this, because you have to draw an arrow from every organism in the chain or web to the decomposers, which makes it look very complicated.","The book's simple food web: banana → fruit bat, banana → parrot, fruit bat → python, parrot → python; all four have arrows to microorganisms.","The book asks: write a food chain of your own and add decomposers; are decomposers producers or consumers? Explain."],
    "s.7.4.learnDetail.7": ["Activity 7.4.2: the toadstools in the photo are easy to see without a microscope, so they are not microorganisms; the part of the fungus you cannot see is inside the log, breaking it down.","Activity 7.4.3 (groups of three) asks: is this fungus a decomposer? Is it a microorganism? A slug eats the fungus – where did the slug's energy originally come from? Draw a food chain for that answer. Apart from fungi, what other microorganisms act as decomposers?","Activity 7.4.4: on a large sheet of paper, make a mind map linking ideas about food webs, microorganisms and decay; compare and explain mind maps with a partner."],
    "s.7.4.learnDetail.8": ["The microorganism that causes malaria is spread by mosquitoes. In some countries a chemical called DDT is used to kill mosquitoes, which reduces malaria cases; but DDT also harms other animals.","The World Health Organization (WHO) thinks we need to carry on using DDT until better alternatives are found, to save thousands of human lives.","The Worldwide Fund for Nature (WWF) thinks we need to stop using DDT as soon as possible, to protect the environment.","Project: in groups of three or four, represent the WHO or the WWF, build your case and debate. When using the internet: think about who produced the web page, whether it is unbiased, and use only the most relevant information."],
    "s.7.4.learnDetail.9": ["When an animal eats another animal that has DDT in its body, it also eats the DDT; if an animal moves, it takes the DDT with it.","Example: Midway Atoll is thousands of miles from any land where DDT is used, but DDT has been found in the black-footed albatrosses there.","DDT is very poisonous to fish and quite poisonous to frogs and other amphibians; we are not sure yet how poisonous it is to humans."],
    "s.7.4.learnDetail.10": ["The eggs break before the young birds hatch. In the USA, numbers of bald eagles fell when DDT was used; DDT was banned in 1972.","The book's graph: the average number of young per breeding area fell from about 1.26 (1966) to a lowest value of about 0.46 (1974), then rose to about 1.12 (1981).","Indoor residual spraying: in many countries with malaria, DDT is sprayed inside houses; it sticks to the walls and kills mosquitoes for up to 6 months, and needs much less DDT than spraying outside."],
    "s.7.4.learnDetail.11": ["In 2015, 212 million people had malaria and 429 000 died; in 2016 there were 216 million cases and 445 000 deaths. More than two-thirds of the people dying from malaria are children under 5.","Malaria occurs where the mosquitoes that transmit it live – only in tropical or subtropical countries. The Earth's mean temperature is rising, which may let these mosquitoes move into new areas.","Other methods: other chemicals to kill mosquitoes (most are much more expensive than DDT); sleeping under a bed net reduces the risk of bites; the best vaccine so far needs four injections and only halves the risk.","DDT is persistent: if it gets into a lake or river, over half is still there 150 years later. DDT is completely banned in 34 countries; many, including India and many African countries, still use it."],
    "s.7.4.extend": ["Decomposers are consumers: they do not make food from light but feed on the ready-made organic matter in dead bodies and waste.","In Vietnam, many families compost organic waste (vegetable peel, fallen leaves): microorganisms break it down into nutrients for plants.","Lactic acid bacteria turn the sugar in milk into acid to make yoghurt: the acid lowers the pH and gives the sour taste.","Because an animal eats a great many prey, DDT builds up most at the end of a food chain (for example birds of prey) – this is called biomagnification."],
    "s.7.4.figcap": ["Without and with decomposers: dead bodies and dung pile up, or become nutrients for plants","The nutrient cycle: decomposers return nutrients to the soil for plants","The activity: watching a piece of fruit decay","A food web with decomposers added (after the book's diagram)","A fungus on a log: the visible part is not a microorganism; the threads inside are breaking the wood down","DDT passes along a food chain to birds of prey and makes their egg shells thin","Average number of young birds per breeding area, 1966–1981 (redrawn from the book's data)"],
    "s.7.2.learn": ["**Ecology** is the study of organisms in their environment; organisms that live together affect one another.","Microorganisms have important roles in the environment, including in **food chains** and **food webs**.","The energy in food begins in the Sun; plants use energy from sunlight to make their own food.","An animal that eats a plant gets energy – this is energy transfer; a food chain shows it with arrows.","The first organism in a food chain is a **producer**.","All the other organisms are **consumers**; animals are always consumers.","Consumers that eat only plants are **herbivores**; those that eat other animals are **carnivores**.","Animals that catch, kill and eat other animals are **predators**; the animals they eat are their **prey**.","Many food chains linked by feeding habits make a food web.","The food web of the African plains links 9 organisms with 13 arrows.","Activity: write feeding descriptions so another group can build the food web with cards and arrows.","Food chains and food webs are a model of how organisms in one place depend on each other for food."],
    "s.7.2.learnDetail.0": ["For example, one species of animal may eat another animal.","For example, a plant may provide shelter for an animal.","The book asks (Getting started): tigers eat deer, deer eat grass – write this as a food chain; tigers also eat langur monkeys and deer are also eaten by leopards – add these to make a food web."],
    "s.7.2.learnDetail.1": ["The rest of the unit looks at how microorganisms affect other organisms in their environment.","This topic looks at how food chains and food webs describe how energy, in the form of food, is transferred between animals and plants.","The next topic looks at how microorganisms fit into food chains and food webs."],
    "s.7.2.learnDetail.2": ["Arun has chicken and rice for lunch; it gives him a lot of energy. The food you eat gives you energy.","The book asks: how did the energy get into the food? Energy from the Sun reaches the Earth in sunlight.","Some of the energy from sunlight goes into the food that the plant stores in its roots, stems, fruits and leaves."],
    "s.7.2.learnDetail.3": ["When an animal – such as Arun – eats part of a plant, it eats the food the plant made; this is how the animal gets energy.","A food chain shows how the energy passes from the Sun into the rice and then into Arun's body.","The arrows show energy passing from the Sun to the plant, then to the rice, then to Arun."],
    "s.7.2.learnDetail.4": ["Plants use energy from the Sun to produce food.","So a food chain always begins with a plant."],
    "s.7.2.learnDetail.5": ["Animals have to eat ready-made food to get their energy.","They consume (eat) plants or other animals."],
    "s.7.2.learnDetail.6": ["Herbivores consume only plants.","Carnivores consume other animals."],
    "s.7.2.learnDetail.7": ["The book asks: the chicken Arun ate had eaten wheat (a plant) – draw a food chain showing how energy passed from the Sun to Arun when he ate the chicken.","The book asks: draw a food chain showing how energy from the Sun passed into you when you ate something for breakfast or lunch."],
    "s.7.2.learnDetail.8": ["Two food chains on the African plains: acacia tree → springbok → cheetah; grass → termite → aardvark → leopard.","A **food web** is a diagram showing how the organisms in these chains, and some others, are connected by their feeding habits.","Put your finger on the acacia tree, then move it to the springbok, then to the cheetah: you are tracing the path of the energy along a food chain. Do the same for the chain that begins with grass and ends with a leopard."],
    "s.7.2.learnDetail.9": ["At the bottom of the web are acacia and grass. Eating grass: springbok, zebra, termite; springbok also eat acacia.","Springbok are eaten by hyenas, leopards and cheetahs; zebras are eaten by leopards and cheetahs.","Termites are eaten by aardvarks; aardvarks are eaten by leopards and cheetahs; hyenas are eaten by leopards.","The book asks: write two more food chains from the web; name the two producers; how many consumers and how many herbivores are there; name two carnivores; name two predators and their prey."],
    "s.7.2.learnDetail.10": ["Work in a group of four or five. You need: a food web diagram (each group a different one), cards to write on, lined paper, arrows cut out of card or paper.","Step 1: write each organism's name on a card. Step 2: write the descriptions on lined paper, for example 'Springbok eat acacia trees.', 'Termites are eaten by aardvarks.', 'Cheetahs and leopards eat zebras.'","Step 3: give your cards and arrows to another group and ask them to use your descriptions to build the food web.","Self-assessment: could the other group build the web? Did they make the arrows point the correct way? How could you make your descriptions easier to follow?"],
    "s.7.2.learnDetail.11": ["In a group of two or three, discuss how well the African food web shows what really happens on the African plains.","Ideas to discuss: how complete is the food web? Is it possible to draw a totally complete food web?","Then complete the sentences 'I think the food web is a useful model because …' and 'I think the food web is not a perfect model because …'."],
    "s.7.2.extend": ["Tip for reading arrows: 'is eaten by' (grass → goat means grass is eaten by the goat). Drawing the arrow the wrong way round is a very common mistake.","Omnivores eat both plants and animals, for example pigs, chickens and humans.","Examples in Vietnam: rice field: rice → rat → snake → owl; mangrove forest: mangrove leaves → crab → egret.","In ponds and lakes, algae are producers too: they photosynthesise and are food for shrimps and small fish."],
    "s.7.2.figcap": ["Plants use light energy to make their own food and store it in roots, stems, fruits and leaves","Arun's food chain: the arrows show energy passing from the Sun to the rice plant and then to Arun","Naming the organisms in a food chain by how they get their food","Two food chains of the African plains and the role of each organism","The food web of the African plains: each arrow points from the organism eaten to the organism that eats it","Turning feeding descriptions into arrows that point the right way"],
    "g.0.def": "A living organism so small that it can only be seen clearly with a microscope.",
    "g.1.def": "Very small single-celled microorganisms found everywhere; most are harmless.",
    "g.2.def": "A group of organisms that includes single-celled yeast, thread-like moulds and large mushrooms.",
    "g.3.def": "A group of many cells that came from one original microorganism, big enough to see with the naked eye.",
    "g.4.def": "With all living things, including microorganisms, killed.",
    "g.5.def": "A diagram using arrows to show energy passing from one organism to the organism that eats it.",
    "g.6.def": "An organism that makes its own food using energy from sunlight (plants, algae); it is always first in a food chain.",
    "g.7.def": "An organism that has to eat ready-made food (plants or other animals) to get energy.",
    "g.8.def": "An organism that gets energy by breaking down dead organisms and waste, returning nutrients to the soil.",
    "g.9.def": "Substances that living things need for energy or to grow.",
    "ex.7.1.q": "One bacterial cell lands on agar jelly. Every 20 minutes each cell divides into 2. How many cells are there after 3 hours (assume no cells die)?",
    "ex.7.1.steps": ["Change the time into minutes: 3 hours = 3 × 60 = 180 minutes.","Number of divisions: 180 ÷ 20 = 9.","Each division doubles the number of cells: 1 → 2 → 4 → 8 → …, that is 2 multiplied by itself 9 times.","2⁹ = 512 cells. Carrying on like this, after about a day there are millions of cells: a colony you can see."],
    "ex.7.1.prompts": ["The division time is in minutes but the experiment time is in hours. What must you do first?","How many 20-minute periods are there in 180 minutes?","After each division, how does the number of cells change?","Starting from 1, what do you get after doubling 9 times?"],
    "ex.7.1.goal": "Understand how one single microorganism can grow into a visible colony.",
    "ex.7.1.twist": "Still starting from 1 cell, dividing every 20 minutes. After how many minutes, at the least, is the number of cells more than 1000?",
    "q.7.1-01.hints": ["What does the word 'micro' suggest about size?","Is a microorganism a living thing?","Do all microorganisms cause disease?"],
    "q.7.1-01.explain": "A microorganism is a living organism that is very small and can only be seen clearly with a microscope. Many are harmless; dust is not alive; an organelle is part of a cell, not an organism.",
    "q.7.1-02.hints": ["Which organism can you see clearly with your naked eye?","Is yeast a single-celled fungus or a large fungus?","Can you see the algae and protozoa in a drop of pond water without a microscope?"],
    "q.7.1-02.explain": "Bacteria, yeast, protozoa and microscopic algae are all microorganisms. An earthworm is an animal big enough to see with the naked eye.",
    "q.7.1-03.hints": ["The word shares most letters with 'bacteria'. Only the ending changes.","Many Latin science words have a singular ending '-um' and a plural ending '-a'. Can you think of an example?","Try replacing the '-a' at the end of 'bacteria' with '-um'."],
    "q.7.1-03.explain": "The singular is bacterium and the plural is bacteria (like alga/algae, fungus/fungi, protozoan/protozoa).",
    "q.7.1-04.hints": ["Are there bacteria in the human gut? Do they make us ill all the time?","Do bacteria live only in dirty places, or everywhere?","A few kinds may cause disease, but is that true of all of them?"],
    "q.7.1-04.explain": "Common mistake: thinking that all bacteria are germs. In fact bacteria are everywhere, most are harmless and many are useful (living in our gut, making yoghurt, decaying dead things). Only a few kinds cause disease.",
    "q.7.1-05.hints": ["What does 'sterile' mean?","If the jelly already had living microorganisms on it, could you tell which colonies came from the air?","Where do we want to measure microorganisms from in this experiment?"],
    "q.7.1-05.explain": "Sterile means every living thing has been killed. Then the colonies that grow can only come from microorganisms that fell from the air, so the result can be trusted.",
    "q.7.1-06.hints": ["A colony can contain millions of microorganisms. Do we want them on our hands or in our nose?","What does the sticky tape stop happening to the lid?","What could our breath carry onto the jelly?"],
    "q.7.1-06.explain": "Taping the lid, not opening the dish after growth and not breathing or talking over the jelly are safe steps. Smelling or touching colonies could get microorganisms into your body, even though it is unlikely they are harmful.",
    "q.7.1-07.hints": ["A mould is made of thin threads. What does a mass of threads look like?","What kind of edge does a bacterial colony usually have?","Can viruses grow into colonies on jelly by themselves?"],
    "q.7.1-07.explain": "Bacterial colonies are usually round and shiny with smooth edges. Fungal (mould) colonies are made of threads, so they look furry with rough edges. Viruses do not grow on jelly by themselves.",
    "q.7.1-08.hints": ["Pond water has two groups of microorganism: one animal-like, one plant-like. Which group has chloroplasts?","Can protozoa make their own food using light?","The plant-like group in water is green; its Vietnamese name starts with 't'."],
    "q.7.1-08.explain": "An alga (plural algae) is plant-like: it has chloroplasts and photosynthesises. Protozoa are animal-like and must eat ready-made food.",
    "q.7.1-09.hints": ["Change 3 cm into millimetres: how many mm are in 1 cm?","How many bacteria fit in each millimetre?","Multiply the number of millimetres by the number of bacteria per millimetre."],
    "q.7.1-09.explain": "3 cm = 30 mm. Each mm holds 1000 bacteria, so the leaf holds 30 × 1000 = 30 000 bacteria. So one bacterium is only about 0.001 mm long.",
    "q.7.1-10.hints": ["Like all organisms, what are microorganisms made of?","Is the white powder on grapes one organism or a huge number of them together?","Does a virus have cells? Can it grow by itself outside other cells?"],
    "q.7.1-10.explain": "Microorganisms are organisms made of cells. Viruses have no cells and can only reproduce inside other cells, so they are not usually counted as microorganisms. The white powder on grapes is millions of yeast cells; each cell can only be seen with a microscope.",
    "ex.7.2.q": "Use the food web in the diagram (a rice field). How many food chains are there in this food web altogether (each chain starts at a producer and ends at an animal that nothing eats)?",
    "ex.7.2.steps": ["Find the producers (no arrows point into them): rice and grass. Find the end animal (no arrows leave it): only the owl.","Go from rice through the rat: rice → rat → owl and rice → rat → snake → owl. That gives 2 chains.","Go from rice through the grasshopper: grasshopper → frog → snake → owl, or grasshopper → spider → frog → snake → owl. That gives 2 more chains.","From grass you can only go through the grasshopper, so there are 2 chains as in step 3. Total: 2 + 2 + 2 = 6 food chains."],
    "ex.7.2.prompts": ["Where does each chain start and end? How can you spot those places in the diagram?","From rice, if you go through the rat, which routes lead to the owl?","From rice through the grasshopper, how many ways are there to reach the frog (directly or through the spider)?","Which animals does grass lead to? Add up all the routes you counted."],
    "ex.7.2.goal": "Read a food web systematically so that no food chain is missed.",
    "ex.7.2.twist": "If the spiders disappeared from the field, how many food chains would the web have left?",
    "q.7.2-01.hints": ["In real life, which eats which: does the goat eat the grass or the grass eat the goat?","When the goat eats grass, where does the energy go from and to?","The arrow points from the grass to the goat. So does it describe energy or the action of eating?"],
    "q.7.2-01.explain": "Common mistake: reading the arrow as 'eats' and drawing it the wrong way round. The arrow shows the direction energy is transferred: from the grass (food) to the goat (eater), then from the goat to the tiger. Read it as 'is eaten by'.",
    "q.7.2-02.hints": ["Does this organism 'make' food or does it have to 'eat' ready-made food?","We call animals consumers. What is the opposite of 'consumer' in a food chain?","To make something is to 'produce' it. What do we call something that produces?"],
    "q.7.2-02.explain": "The first organism in a food chain is a producer, usually a plant or an alga. It makes its own food using energy from sunlight.",
    "q.7.2-03.hints": ["How does the rice plant make its own food?","Soil, water and fertiliser give the plant materials. But where does the energy to make food come from?","Where does the food chain start, even before the rice plant?"],
    "q.7.2-03.explain": "The rice plant uses energy from sunlight to make food and stores it in the grains. When Nam eats the rice, that energy passes to him: Sun → rice → Nam.",
    "q.7.2-04.hints": ["Which organism is the producer here? Where does it go?","Arrows must point from the food to the eater. What does the crab eat?","Check: energy goes from the leaves to the crab, and then to which animal?"],
    "q.7.2-04.explain": "The chain starts with the producer (mangrove leaves) and the arrows point to the eater: mangrove leaves → crab → heron. The other versions reverse the direction of energy.",
    "q.7.2-05.hints": ["Which organisms are consumers: those that make their own food, or those that eat others?","How many producers are in the diagram? They are not counted.","Count all the boxes, then subtract the number of producers."],
    "q.7.2-05.explain": "There are 8 organisms; rice and grass are producers. That leaves 6 consumers: grasshopper, rat, spider, frog, snake and owl.",
    "q.7.2-06.hints": ["Herbivores receive arrows from which kind of organism?","Look at the arrows leaving rice and grass: which animals do they point to?","Do those animals eat any other animals?"],
    "q.7.2-06.explain": "The arrows from rice and grass go to the grasshopper and the rat. These two eat only plants, so there are 2 herbivores.",
    "q.7.2-07.hints": ["Do carnivores receive arrows from plants or from animals?","For each animal, look at the arrows pointing INTO it. Where do they come from?","Leave out any animal whose arrows come only from rice or grass."],
    "q.7.2-07.explain": "The frog eats grasshoppers and spiders; the spider eats grasshoppers; the snake eats frogs and rats; the owl eats rats and snakes. All four eat animals, so they are carnivores. The grasshopper and rat eat plants.",
    "q.7.2-08.hints": ["The longest chain passes through as many animals as possible. Is there an animal you can squeeze in between two others?","From the grasshopper to the frog you can go directly, or through which other animal?","Write the whole chain from a producer to the owl, then count the names."],
    "q.7.2-08.explain": "The longest chain is rice (or grass) → grasshopper → spider → frog → snake → owl, with 6 organisms.",
    "q.7.2-09.hints": ["Is the snake a predator or prey of the rat?","If there are fewer predators, are the prey eaten more or less?","Owls still eat rats, but is the total number of rats eaten the same as before?"],
    "q.7.2-09.explain": "The snake is a predator of the rat. With fewer snakes, fewer rats are eaten, so the number of rats rises (owls still eat some, but not enough to make up for it). More rats may then damage more rice.",
    "q.7.2-10.hints": ["How many species live in a real field? Can a diagram show them all?","Is it correct or incorrect for the arrow to point to the eater?","Does the food web tell you how many rats an owl eats each week?"],
    "q.7.2-10.explain": "A food web is useful because it shows how species depend on each other for food, but it is not perfect: it leaves out many species (small insects, microorganisms…), does not show amounts eaten, and changes with the seasons. Arrows pointing to the eater is the correct convention.",
    "ex.7.3.q": "Two identical slices of bread are made equally damp, left open to the air for 30 minutes and then wrapped. Slice A is kept at 25 °C and slice B in a fridge at 5 °C. Percentage of surface covered with mould: Day: 0, 2, 4, 6 | Slice A (25 °C): 0, 10, 35, 70 | Slice B (5 °C): 0, 0, 2, 5. On day 6, how many percent more of slice A's surface is covered with mould than slice B's?",
    "ex.7.3.steps": ["The independent variable (changed) is temperature; the dependent variable (measured) is the percentage of surface with mould. The type of bread, water and time open to the air are kept the same.","Read the table on day 6: slice A has 70 %, slice B has 5 %.","Difference: 70 − 5 = 65 (percentage points).","Conclusion: at a warm temperature mould grows much faster, so the bread decays faster. That is why we keep food in a fridge."],
    "ex.7.3.prompts": ["Between the two slices, what was deliberately made different? What was measured?","In the day 6 column, what percentage of mould does each slice have?","To find 'how many more', which operation do you use?","From the data, what can you conclude about temperature and the speed of decay?"],
    "ex.7.3.goal": "Read a results table, identify the variables and draw a conclusion from real data.",
    "ex.7.3.twist": "If a slice C were kept at 15 °C, what range would you predict for its percentage of mould on day 6? Explain using the table.",
    "q.7.3-01.hints": ["'Decay' means to break down. Which word with the same meaning is in the name of these organisms?","Another English word for 'break down' is 'decompose'.","Add the ending that means 'a thing that does this' to the verb."],
    "q.7.3-01.explain": "Decomposers, such as many bacteria and fungi, feed on dead organic matter and break it down.",
    "q.7.3-02.hints": ["Organic matter is made by living things. What is paper made from?","Which plant does cotton come from?","Are iron, glass and sand made by living organisms?"],
    "q.7.3-02.explain": "Paper (from wood), cotton (from the cotton plant) and banana peel were all made by living things, so they are organic matter. Iron, glass and sand come from rocks, not living things.",
    "q.7.3-03.hints": ["Do the patches get bigger day by day? Does dust grow?","Under a microscope the patches are made of very thin threads. Which organisms are made of threads?","What does the lesson call the microscopic fungus that grows on food?"],
    "q.7.3-03.explain": "It is mould, a microscopic fungus made of threads. Each patch is a colony of millions of threads and cells feeding on the bread and breaking it down.",
    "q.7.3-04.hints": ["If you looked at the brown part under a microscope, what might you see?","A banana is organic matter. Which organisms feed on dead organic matter?","Food in a fridge spoils more slowly. Does that suggest living things are involved?"],
    "q.7.3-04.explain": "Common mistake: thinking that food 'goes off by itself' with no living things involved. In fact bacteria and fungi (decomposers) feed on the banana and break it down, making it brown, soft and smelly.",
    "q.7.3-05.hints": ["What did Linh deliberately make different between the two slices?","Is the amount of mould something she changes or something she observes?","Are the type of bread and the water kept the same?"],
    "q.7.3-05.explain": "Linh changes the temperature (warm and cold), so it is the independent variable. The amount of mould is the dependent variable; the type of bread and water are control variables (kept the same).",
    "q.7.3-06.hints": ["Which variable does Linh want to change and compare? Can that one be kept the same?","If one slice were wetter, could you tell whether the extra mould was due to temperature or to water?","How does the time open to the air affect how many microorganisms land on the bread?"],
    "q.7.3-06.explain": "Only the temperature is changed. The size and type of bread, the water and the time open to the air must be kept the same, so any difference in mould can only be due to temperature.",
    "q.7.3-07.hints": ["In which cases is something that people want to use spoiled?","If nothing broke down fallen leaves, what would a forest be like after many years?","Which case helps to 'tidy up' nature?"],
    "q.7.3-07.explain": "Decay of fallen leaves is useful: it clears waste and returns nutrients to the soil. Mouldy bread, rotten strawberries and a rotting boat are harmful decay because they spoil things people use.",
    "q.7.3-08.hints": ["As the temperature rises from 5 to 35 °C, how does the number of mould spots change?","Was 100 °C tested? Can you draw conclusions about temperatures that were not tested?","A good conclusion only states what the data show, within the range tested."],
    "q.7.3-08.explain": "The number of spots rises 1 → 6 → 15 → 22 as the temperature rises from 5 to 35 °C. You cannot conclude anything about 100 °C because it was not tested; in fact very high temperatures kill microorganisms.",
    "q.7.3-09.hints": ["Which three results are close together? Which one is far away from them?","After leaving out the anomalous result, how many numbers are left? What is their total?","Mean = total ÷ number of results."],
    "q.7.3-09.explain": "The result 3 is far from 12, 13 and 14, so it is anomalous (perhaps that slice was drier or was miscounted). Mean = (12 + 14 + 13) ÷ 3 = 39 ÷ 3 = 13 spots.",
    "q.7.3-10.hints": ["Which factor is the hypothesis about? That must be the only variable changed.","In each plan, is any other variable (temperature, type of bread) also changed?","Does the plan have a slice to compare with and record results regularly?"],
    "q.7.3-10.explain": "A fair test changes only the moisture and keeps the type of bread, time open to the air and temperature the same, recording results every day. The other plans also change temperature or type of bread, or have nothing to compare with.",
    "ex.7.4.q": "A garden food web: leaves → caterpillar → bird; leaves → snail → bird; snail → frog. If 'decomposers' are added to the web (an arrow from every organism to them), how many arrows will the web have altogether?",
    "ex.7.4.steps": ["Count the feeding arrows: leaves → caterpillar, caterpillar → bird, leaves → snail, snail → bird, snail → frog: 5 arrows.","List the different organisms: leaves, caterpillar, snail, bird, frog: 5 organisms.","Every organism, when it dies (or produces waste), passes energy to the decomposers: 5 more arrows.","Total: 5 + 5 = 10 arrows. Now you can see why diagrams usually leave decomposers out!"],
    "ex.7.4.prompts": ["Each 'is eaten by' link is one arrow. How many such links are there?","How many different organisms are in the web (without counting any twice)?","Is there any organism that never dies or never makes waste? So how many arrows to the decomposers are needed?","Add the two kinds of arrows together."],
    "ex.7.4.goal": "See that decomposers receive energy from every link in a food web.",
    "ex.7.4.twist": "Add a hawk that eats both birds and frogs. How many arrows does the web (with decomposers) have now?",
    "q.7.4-01.hints": ["Do decomposers have chloroplasts to photosynthesise?","Do all living things need energy?","What is the fungus growing on elephant dung feeding on?"],
    "q.7.4-01.explain": "Decomposers feed on dead organisms and waste (dung, fallen leaves…). The energy in them passes to the decomposers. They cannot photosynthesise.",
    "q.7.4-02.hints": ["The agar jelly in a Petri dish also contains these substances to feed microorganisms.","They are substances that help living things get energy or grow.","The English word starts with 'nutri…', like 'nutrition'."],
    "q.7.4-02.explain": "They are nutrients. Decomposers return nutrients to the soil, and plants take them up to grow.",
    "q.7.4-03.hints": ["What energy do producers use to make food?","Does the mould on bread make its own food or eat the bread?","Is 'making soil' the same as 'making food from light'?"],
    "q.7.4-03.explain": "Common mistake: thinking decomposers are producers because they 'make' rich soil. In fact they cannot make food from light; they eat ready-made organic matter (dead bodies, waste), so they are consumers.",
    "q.7.4-04.hints": ["What do arrows in a food web always show the direction of?","Do decomposers feed on organisms while they are alive or after they die?","The arrows point INTO the decomposers: where does the energy go?"],
    "q.7.4-04.explain": "Arrows show the direction of energy. When an organism dies or produces waste, the energy in it passes to the decomposers. Decomposers do not hunt living organisms.",
    "q.7.4-05.hints": ["Who would clear away the fallen leaves and dead animals?","Could the nutrients 'locked' in dead bodies get back into the soil?","If plants lacked nutrients, what would happen to the animals that eat them?"],
    "q.7.4-05.explain": "Without decomposers, waste and dead bodies would pile up and nutrients would not return to the soil. Plants would grow less well, and so animals would have less food.",
    "q.7.4-06.hints": ["Does a fungus have chloroplasts? Where does it get its food?","Which organism made the wood of the log, and using what energy?","Write the food chain starting with the Sun and ending with the slug."],
    "q.7.4-06.explain": "The chain is Sun → tree (wood) → fungus → slug. The tree used sunlight to make the food in its wood; the fungus (a decomposer) fed on the wood; the slug ate the fungus. So the energy originally came from the Sun.",
    "q.7.4-07.hints": ["How do you work out the mean of a group?","What is the total of the five leaves next to dung? What do you divide by?","Do the same for the group away from dung, then subtract the two means."],
    "q.7.4-07.explain": "Next to dung: (14 + 12 + 15 + 11 + 13) ÷ 5 = 65 ÷ 5 = 13 cm. Away from dung: (9 + 10 + 8 + 11 + 7) ÷ 5 = 45 ÷ 5 = 9 cm. Difference: 13 − 9 = 4 cm.",
    "q.7.4-08.hints": ["Are the two means different? Which way do the results point?","Compare the shortest leaf near dung (11 cm) with the longest leaf away from dung (11 cm). Is 'every leaf' true?","Are 5 leaves at one dung pat enough to say 'always' for every field?"],
    "q.7.4-08.explain": "The mean near dung (13 cm) is bigger than away from it (9 cm), so the results support the idea. But the sample is small and from one place; it should be repeated with many leaves and many dung pats to be sure. The word 'always' is too strong.",
    "q.7.4-09.hints": ["Does an acid have a pH above or below 7?","Fresh milk is nearly neutral. When acid is added, does it become more acidic or less?","The more acidic something is, is its pH number bigger or smaller?"],
    "q.7.4-09.explain": "Lactic acid bacteria make acid from the sugar in milk. The acid makes it more acidic, so the pH becomes lower (for example from about 6.7 to about 4.5).",
    "q.7.4-10.hints": ["If the chemical does not break down, is it lost when the animal is eaten?","A large fish eats many small fish in its life. How does its amount of chemical compare with one small fish?","The animal at the end of the chain eats many animals from the link before. So where does the chemical build up?"],
    "q.7.4-10.explain": "A chemical that does not break down is passed on and builds up along the chain: each animal eats many from the link before. So the fish eagle at the end of the chain collects the most (as happened with DDT making birds of prey lay thin-shelled eggs).",
    "u.challenge.title": "Vietnam Challenge",
    "u.challenge.intro": "Microorganisms are in every jar of pickled vegetables, every spell of humid 'nồm' weather and every rice field in Vietnam – use your knowledge to explain them!",
    "q.ch-01.q": "To make pickled mustard greens, the vegetables are soaked in salty water. After 2–3 days they taste sour and keep longer than fresh vegetables. Which explanation is correct?",
    "q.ch-01.choices": ["Lactic acid bacteria change sugar in the vegetables into acid; the low pH makes it hard for rotting microorganisms to grow.","The salt turns into acid by itself, so the pickle is sour; no living things take part in this.","The pickle is sour because mould makes the vegetables rot; the more sour, the more mould there is.","Salty water kills every microorganism in the vegetables, so the pickle slowly turns sour and never spoils."],
    "q.ch-01.hints": ["Which kind of substance causes a sour taste?","Who made that substance in the jar? Remember how bacteria make yoghurt.","How does a low-pH environment affect the microorganisms that cause rotting?"],
    "q.ch-01.explain": "Lactic acid bacteria (already on the vegetables) change sugar into lactic acid, making the pickle water sour with a low pH. In low pH and high salt, most rotting microorganisms grow poorly, so the pickles keep longer. Pickles can still spoil if kept too long or if mould gets in.",
    "q.ch-02.q": "During the humid 'nồm' season in northern Vietnam (February–April), bread, clothes and walls go mouldy very easily. What is the main reason?",
    "q.ch-02.choices": ["The air is very damp and it is getting warmer — the conditions mould spores need to grow.","Water vapour in the air condenses and then turns into mould by itself on everything in the house.","The 'nồm' season is very sunny, so mould photosynthesises a lot and grows very fast.","The cold kills all the bacteria, so mould no longer has any competition."],
    "q.ch-02.hints": ["In the bread experiments, does damp or dry bread go mouldy faster?","Does mould have chloroplasts? Does it need sunlight?","Where are mould spores already present? What conditions are they waiting for?"],
    "q.ch-02.explain": "Mould spores are always in the air. In the 'nồm' season the humidity is very high and it is getting warmer (about 18–25 °C), so mould grows quickly on anything containing organic matter. Mould does not photosynthesise and does not appear from water vapour by itself.",
    "q.ch-03.q": "A bowl of leftover rice left out at 30 °C has 1 bacterium on it. Every 20 minutes this bacterium divides once (1 into 2). After 4 hours, if no cells die, how many bacteria are there?",
    "q.ch-03.hints": ["How many minutes are in 4 hours? How many divisions happen in that time?","After each division, what is the number of bacteria multiplied by?","Work out 2 to the power of (the number of divisions)."],
    "q.ch-03.explain": "4 hours = 240 minutes; 240 ÷ 20 = 12 divisions. Number of bacteria = 2¹² = 4096. That is why leftover rice should not be left at room temperature for long.",
    "q.ch-04.q": "Choose ALL the correct statements.",
    "q.ch-04.choices": ["The yeast used to make bread is a single-celled microorganism.","All bacteria cause disease in humans.","The straw mushroom we eat is a microorganism.","Bacteria and fungi are the most important decomposers.","Single-celled algae can photosynthesise, so they are producers."],
    "q.ch-04.hints": ["For each statement ask: can it be seen with the naked eye? Does it make its own food?","A straw mushroom is as big as a finger – do you need a microscope to see it?","One statement says 'all'. A single counter-example makes it false."],
    "q.ch-04.explain": "True: yeast is a single-celled microorganism; bacteria and fungi are the main decomposers; single-celled algae photosynthesise, so they are producers. False: most bacteria are harmless; a straw mushroom is a large fungus you can see with your eyes, so it is not a microorganism.",
    "q.ch-05.q": "In a rice field: caterpillars, rats and sparrows eat rice; frogs and sparrows eat caterpillars; snakes eat frogs and rats; owls eat rats and sparrows. Nothing eats the snakes or owls. How many food chains are there in this food web?",
    "q.ch-05.howto": "Each chain starts at the rice and ends at the snake or the owl. Count all the different routes.",
    "q.ch-05.hints": ["Draw the web on paper: rice at the bottom, snake and owl at the top.","From the rice through the caterpillar: which animals does the caterpillar lead to, and where do they lead?","Do the same for the rat and the sparrow, then add up all the routes."],
    "q.ch-05.explain": "The chains are: rice → caterpillar → frog → snake; rice → caterpillar → sparrow → owl; rice → rat → snake; rice → rat → owl; rice → sparrow → owl. 5 chains in total.",
    "q.ch-06.q": "Using the food web from the previous question, people catch many snakes and owls to sell. What is most likely to happen a few years later?",
    "q.ch-06.choices": ["Rats increase quickly because fewer are eaten, they eat more rice, and the harvest may fail.","Rats decrease because there are no snakes left for rats to eat.","The rice grows better because snakes and owls no longer eat it.","Nothing changes because snakes and owls are at the end of the chains."],
    "q.ch-06.hints": ["Which animals do snakes and owls prey on?","When predators decrease, what happens to their prey?","What do rats eat? If rats increase, what happens to that food?"],
    "q.ch-06.explain": "Snakes and owls eat rats. If they are removed, fewer rats are eaten, so rats increase quickly and damage the rice. Animals at the end of chains still control the numbers of their prey, so losing them affects the whole web.",
    "q.ch-07.q": "A group of students put 20 g of dry leaves in a mesh bag and buried it in damp garden soil. After 2 months they dug it up, cleaned and dried the leaves and found 8 g left. What percentage of the mass of leaves had decayed?",
    "q.ch-07.hints": ["How many grams of leaves were lost?","Percentage = (amount lost ÷ starting amount) × 100. What was the starting mass?","Work out 12 ÷ 20, then multiply by 100."],
    "q.ch-07.explain": "Mass lost: 20 − 8 = 12 g. Percentage decayed = 12 ÷ 20 × 100 = 60 %. The leaves must be dried before weighing so that water does not make the result wrong.",
    "q.ch-08.q": "When making yoghurt at home, Mum keeps the milk jars at about 40 °C for 8 hours and then puts them in the fridge. Which statement correctly explains both steps?",
    "q.ch-08.choices": ["At 40 °C lactic acid bacteria are very active, so the milk ferments quickly; in the fridge all bacteria work very slowly.","Keeping it warm kills all the bacteria in the milk; the fridge helps the useful bacteria multiply faster.","Temperature does not affect bacteria; the warm step and the fridge only make the yoghurt tasty and cool.","Warmth makes the bacteria work, but 100 °C would be even better; the fridge kills all the bacteria."],
    "q.ch-08.hints": ["In the bread experiments, did warm temperatures make microorganisms grow faster or slower?","If the milk went straight into the fridge, would it turn into yoghurt quickly?","At very high temperatures like boiling water, do bacteria survive?"],
    "q.ch-08.explain": "Lactic acid bacteria work well at about 40 °C, so keeping the milk warm makes it ferment quickly. At low temperatures all bacteria work very slowly, so the yoghurt does not get too sour and keeps longer. At 100 °C the bacteria are killed."
  },
  vi: {
    "q.7.1-01.q": "Phát biểu nào mô tả đúng nhất vi sinh vật?",
    "q.7.1-01.choices": ["Sinh vật sống nhỏ đến mức cần kính hiển vi mới nhìn rõ","Bất kì sinh vật nào, to hay nhỏ, có thể gây bệnh cho người","Một hạt bụi hoặc muội than nhỏ bay lơ lửng trong không khí","Một bộ phận nhỏ bên trong tế bào thực vật, ví dụ lục lạp"],
    "q.7.1-02.q": "Những sinh vật nào sau đây là vi sinh vật? Chọn tất cả đáp án đúng.",
    "q.7.1-02.choices": ["vi khuẩn","nấm men","động vật nguyên sinh","tảo cực nhỏ","giun đất"],
    "q.7.1-03.q": "“Bacteria” là danh từ số nhiều. Từ tiếng Anh chỉ MỘT con vi khuẩn là gì?",
    "q.7.1-04.q": "Lan nói: “Vi khuẩn là mầm bệnh. Mọi vi khuẩn đều làm ta ốm, nên phải diệt hết chúng.” Câu trả lời nào đúng?",
    "q.7.1-04.choices": ["Phần lớn vi khuẩn vô hại, nhiều loài sống trong ruột ta; chỉ một số ít loài gây bệnh.","Lan đúng: loài vi khuẩn nào cũng gây bệnh, nên phải diệt hết.","Vi khuẩn chỉ sống ở nơi bẩn, nên người giữ vệ sinh sạch sẽ không có con nào.","Vi khuẩn không phải vật sống, nên dù ở đâu chúng cũng không thể gây hại."],
    "q.7.1-05.q": "Để nuôi vi sinh vật từ không khí, em dùng đĩa Petri và thạch agar vô trùng. Vì sao chúng phải vô trùng?",
    "q.7.1-05.choices": ["Để mọi khuẩn lạc mọc lên chắc chắn chỉ đến từ không khí mà ta đang kiểm tra","Để thạch không bị chảy","Để vi sinh vật trong không khí bị giết khi rơi xuống","Để dễ ghi nhãn lên đĩa"],
    "q.7.1-06.q": "Những cách làm nào sau đây là an toàn khi làm việc với đĩa nuôi vi sinh vật từ không khí? Chọn tất cả đáp án đúng.",
    "q.7.1-06.choices": ["Dán nắp đĩa vào đáy bằng băng dính","Không mở đĩa sau khi khuẩn lạc đã mọc","Không thở hay nói chuyện ngay trên mặt thạch đang mở","Ngửi khuẩn lạc để biết chúng là gì","Sờ vào khuẩn lạc xem nó có xù lông không"],
    "q.7.1-07.q": "Sau bốn ngày, một đĩa có hai kiểu khuẩn lạc. Kiểu P: tròn, bóng, mép nhẵn. Kiểu Q: bông xốp, như có lông, mép xù xì. Nhận định nào hợp lý nhất?",
    "q.7.1-07.choices": ["P là vi khuẩn, Q là nấm","P là nấm, Q là vi khuẩn","Cả hai đều là tảo","Cả hai đều là virus"],
    "q.7.1-08.q": "Trong nước ao, em thấy một sinh vật đơn bào có lục lạp và tự tạo thức ăn nhờ ánh sáng, giống thực vật. Đó là loại vi sinh vật nào? (một từ tiếng Anh hoặc tiếng Việt)",
    "q.7.1-09.q": "1000 vi khuẩn xếp nối đuôi nhau dài 1 mm. Có thể xếp nối đuôi bao nhiêu vi khuẩn như thế dọc một chiếc lá dài 3 cm?",
    "q.7.1-10.q": "Virus còn nhỏ hơn vi khuẩn nhưng thường không được gọi là vi sinh vật. Nấm men nhìn thấy được như lớp bột trắng trên quả nho nhưng VẪN được gọi là vi sinh vật. Giải thích nào tốt nhất?",
    "q.7.1-10.choices": ["Virus không có cấu tạo tế bào; lớp “bột” nấm men là hàng triệu tế bào, mỗi tế bào chỉ thấy qua kính hiển vi.","Virus quá nhỏ nên không đáng kể; thứ gì nhìn thấy được mà không cần kính hiển vi thì không phải vi sinh vật.","Virus vô hại còn nấm men gây bệnh, nên chỉ nấm men được tính là vi sinh vật.","Nấm men là thực vật nhỏ, virus là động vật nhỏ, và chỉ thực vật mới được tính là vi sinh vật."],
    "q.7.2-01.q": "Một chuỗi thức ăn được viết: cỏ → dê → hổ. Các mũi tên cho biết điều gì?",
    "q.7.2-01.choices": ["Hướng năng lượng truyền, từ thức ăn sang con vật ăn nó","“Ăn”: cỏ ăn dê và dê ăn hổ","Sinh vật nào to hơn","Thứ tự các con vật đi săn"],
    "q.7.2-02.q": "Sinh vật đứng đầu chuỗi thức ăn, dùng năng lượng ánh sáng Mặt Trời để tự tạo thức ăn, được gọi là gì?",
    "q.7.2-03.q": "Nam ăn một bát cơm. Năng lượng trong hạt gạo ban đầu đến từ đâu?",
    "q.7.2-03.choices": ["Mặt Trời","Đất","Nước trong ruộng lúa","Phân bón người nông dân dùng"],
    "q.7.2-04.q": "Trong rừng ngập mặn, cua ăn lá đước rụng và diệc ăn cua. Chuỗi thức ăn nào được viết đúng?",
    "q.7.2-04.choices": ["lá đước → cua → diệc","diệc → cua → lá đước","cua → lá đước → diệc","lá đước ← cua ← diệc"],
    "q.7.2-05.q": "Dùng lưới thức ăn trong hình (một cánh đồng lúa; tên sinh vật ghi bằng tiếng Anh: rice = lúa, grass = cỏ, grasshopper = châu chấu, rat = chuột, spider = nhện, frog = ếch, snake = rắn, owl = cú). Lưới thức ăn này có bao nhiêu sinh vật tiêu thụ?",
    "q.7.2-06.q": "Dùng lưới thức ăn trong hình (một cánh đồng lúa; tên sinh vật ghi bằng tiếng Anh: rice = lúa, grass = cỏ, grasshopper = châu chấu, rat = chuột, spider = nhện, frog = ếch, snake = rắn, owl = cú). Lưới thức ăn này có bao nhiêu động vật ăn thực vật?",
    "q.7.2-07.q": "Dùng lưới thức ăn trong hình (một cánh đồng lúa; tên sinh vật ghi bằng tiếng Anh: rice = lúa, grass = cỏ, grasshopper = châu chấu, rat = chuột, spider = nhện, frog = ếch, snake = rắn, owl = cú). Những con vật nào là động vật ăn thịt? Chọn tất cả đáp án đúng.",
    "q.7.2-07.choices": ["châu chấu (grasshopper)","chuột (rat)","ếch (frog)","nhện (spider)","rắn (snake)","cú (owl)"],
    "q.7.2-08.q": "Dùng lưới thức ăn trong hình (một cánh đồng lúa; tên sinh vật ghi bằng tiếng Anh: rice = lúa, grass = cỏ, grasshopper = châu chấu, rat = chuột, spider = nhện, frog = ếch, snake = rắn, owl = cú). Tìm chuỗi thức ăn dài nhất trong lưới. Chuỗi đó có bao nhiêu sinh vật?",
    "q.7.2-09.q": "Dùng lưới thức ăn trong hình (một cánh đồng lúa; tên sinh vật ghi bằng tiếng Anh: rice = lúa, grass = cỏ, grasshopper = châu chấu, rat = chuột, spider = nhện, frog = ếch, snake = rắn, owl = cú). Người dân bắt và bán gần hết rắn. Ảnh hưởng ĐẦU TIÊN hợp lý nhất đến chuột là gì, vì sao?",
    "q.7.2-09.choices": ["Số chuột tăng, vì ít chuột bị ăn hơn","Số chuột giảm, vì chuột ăn rắn","Chuột không bị ảnh hưởng, vì cú cũng ăn chuột","Chuột chết hết, vì chuỗi năng lượng bị đứt"],
    "q.7.2-10.q": "Lưới thức ăn là một mô hình. Phát biểu nào là hạn chế thật sự của mô hình lưới thức ăn?",
    "q.7.2-10.choices": ["Nó không thể hiện mọi sinh vật trong môi trường sống và không cho biết mỗi loài ăn bao nhiêu","Nó chỉ sai hướng năng lượng vì mũi tên chỉ về con ăn","Nó không thể biểu diễn sinh vật sản xuất","Nó vô dụng vì ngoài thực tế con vật chỉ ăn đúng một loại thức ăn"],
    "q.7.3-01.q": "Sinh vật làm cho xác sinh vật và chất thải bị phân hủy được gọi là gì?",
    "q.7.3-02.q": "Những vật nào sau đây được làm từ chất hữu cơ? Chọn tất cả đáp án đúng.",
    "q.7.3-02.choices": ["túi giấy","áo phông bằng vải bông","vỏ chuối","đinh sắt","chai thủy tinh","cát"],
    "q.7.3-03.q": "Trên bánh mì cũ mọc những đốm xanh lam, xốp như bông. Đó là gì?",
    "q.7.3-03.choices": ["Nấm mốc: khuẩn lạc của nấm cực nhỏ gồm những sợi mảnh","Bụi trong không khí rơi xuống và dính vào bánh mì ẩm","Những phần bánh mì đã biến thành cây xanh nhỏ xíu","Tinh thể muối và đường thoát ra từ bánh mì khi bánh khô"],
    "q.7.3-04.q": "Một quả chuối để trên bàn một tuần trở nên thâm, mềm và có mùi. Giải thích nào tốt nhất?",
    "q.7.3-04.choices": ["Vi sinh vật ăn quả chuối và phân hủy nó: quả chuối bị thối rữa","Quả chuối tự già đi; không có sinh vật nào tham gia","Không khí biến quả chuối dần dần thành đất","Ánh sáng từ cửa sổ làm quả chuối tan chảy"],
    "q.7.3-05.q": "Linh để một lát bánh mì ẩm trong tủ ấm và một lát giống hệt trong tủ lạnh. Mỗi ngày bạn ghi lại lượng mốc. Biến độc lập (biến bạn thay đổi) là gì?",
    "q.7.3-05.choices": ["Nhiệt độ","Lượng mốc","Loại bánh mì","Lượng nước thêm vào"],
    "q.7.3-06.q": "Trong thí nghiệm của Linh (tủ ấm và tủ lạnh), bạn cần giữ nguyên những biến nào để phép thử công bằng? Chọn tất cả đáp án đúng.",
    "q.7.3-06.choices": ["kích thước và loại bánh mì","lượng nước thêm vào","thời gian để bánh ngoài không khí","nhiệt độ"],
    "q.7.3-07.q": "Trường hợp nào sau đây cho thấy sự phân hủy là CÓ ÍCH?",
    "q.7.3-07.choices": ["Lá rụng trong rừng được phân hủy nên không chất đống","Mốc mọc trên ổ bánh mì trong tủ","Dâu tây trong bát bị mềm và thối","Chiếc thuyền gỗ mục dần và bị rò nước"],
    "q.7.3-08.q": "Các miếng bánh mì được để ở các nhiệt độ khác nhau trong 4 ngày. Nhiệt độ (°C): 5, 15, 25, 35 | Số đốm mốc: 1, 6, 15, 22. Kết luận nào được kết quả này ủng hộ?",
    "q.7.3-08.choices": ["Trong khoảng 5 °C đến 35 °C, nhiệt độ càng cao thì mốc mọc càng nhiều","Mốc mọc tốt nhất ở 5 °C vì lạnh giữ cho bánh không bị khô","Ở 100 °C mốc sẽ mọc còn nhanh hơn nữa vì xu hướng luôn tăng","Nhiệt độ không ảnh hưởng đến mốc; các đốm là do độ ẩm"],
    "q.7.3-09.q": "Bốn lát bánh mì ẩm giống nhau được để ở 25 °C. Số đốm mốc sau 5 ngày: 12, 14, 3, 13. Có một kết quả bất thường. Bỏ kết quả đó ra rồi tính số đốm trung bình.",
    "q.7.3-09.howto": "Trước hết tìm kết quả không hợp với các kết quả còn lại, rồi tính trung bình của ba kết quả kia.",
    "q.7.3-10.q": "Giả thuyết: “Bánh mì ẩm bị phân hủy nhanh hơn bánh mì khô.” Kế hoạch nào là phép thử công bằng tốt nhất cho giả thuyết này?",
    "q.7.3-10.choices": ["Hai lát giống nhau, chỉ thêm 5 cm³ nước vào một lát; để cả hai cùng một chỗ; ghi lượng mốc mỗi ngày.","Thêm nước vào một lát và để ở phòng ấm; lát khô để trong tủ lạnh; kiểm tra cả hai lát mỗi ngày.","Dùng bánh mì trắng cho lát ẩm và bánh mì đen cho lát khô; để cả hai cùng một chỗ.","Làm ướt một lát, để ở chỗ ấm; xem một lần sau một tháng và ghi lượng mốc."],
    "q.7.4-01.q": "Sinh vật phân giải lấy năng lượng từ đâu?",
    "q.7.4-01.choices": ["Xác sinh vật và chất thải của động vật như phân","Trực tiếp từ ánh sáng Mặt Trời, giống cây xanh","Từ đá trong đất","Chúng không cần năng lượng"],
    "q.7.4-02.q": "Khi sinh vật phân giải phân hủy xác sinh vật, chúng trả lại cho đất những chất có ích mà cây cần để lớn. Những chất đó gọi là gì?",
    "q.7.4-03.q": "Sinh vật phân giải là sinh vật sản xuất hay sinh vật tiêu thụ?",
    "q.7.4-03.choices": ["Sinh vật tiêu thụ, vì chúng ăn chất hữu cơ do sinh vật khác tạo ra","Sinh vật sản xuất, vì chúng tạo ra đất mới và chất dinh dưỡng cho cây","Sinh vật sản xuất, vì mọi vi sinh vật đều tự tạo thức ăn từ ánh sáng","Không phải loại nào, vì bản thân sinh vật phân giải không phải vật sống"],
    "q.7.4-04.q": "Một lưới thức ăn có mũi tên từ mọi sinh vật tới ô “sinh vật phân giải”. Các mũi tên này cho biết điều gì?",
    "q.7.4-04.choices": ["Năng lượng truyền từ xác và chất thải của mỗi sinh vật tới sinh vật phân giải","Sinh vật phân giải săn, giết rồi ăn mọi sinh vật trong lưới thức ăn","Mọi sinh vật trong lưới thức ăn lấy năng lượng bằng cách ăn sinh vật phân giải","Sinh vật phân giải trả năng lượng lại cho mọi sinh vật còn sống trong lưới"],
    "q.7.4-05.q": "Hãy tưởng tượng mọi sinh vật phân giải trong một khu rừng bỗng biến mất. Điều gì sẽ xảy ra trong những năm sau đó?",
    "q.7.4-05.choices": ["Lá rụng, xác và phân sẽ chất đống, đất thiếu dần chất dinh dưỡng","Cây tốt hơn vì không có gì bị thối và lá cây luôn khỏe mạnh","Không có gì thay đổi vì sinh vật phân giải không thuộc lưới thức ăn nào","Động vật có nhiều thức ăn hơn vì sinh vật phân giải không còn ăn mất thức ăn của chúng"],
    "q.7.4-06.q": "Một cây nấm mọc trên khúc gỗ đổ và phân hủy gỗ. Một con sên ăn cây nấm. Năng lượng con sên nhận được BAN ĐẦU đến từ đâu?",
    "q.7.4-06.choices": ["Mặt Trời: cây dùng ánh sáng tạo thức ăn trong gỗ, rồi nấm ăn gỗ đó","Cây nấm, vì nấm tự tạo thức ăn từ gỗ nhờ ánh nắng","Đất bên dưới khúc gỗ, vì nấm lấy toàn bộ năng lượng trực tiếp từ đất","Nước mưa ngấm vào khúc gỗ, cho nấm năng lượng để lớn"],
    "q.7.4-07.q": "Một nông dân đo lá cỏ trên đồng có bò. Cạnh phân bò (cm): 14, 12, 15, 11, 13 | Xa phân bò (cm): 9, 10, 8, 11, 7. Chiều dài trung bình ở cạnh phân bò dài hơn ở xa phân bò bao nhiêu cm?",
    "q.7.4-07.howto": "Tính trung bình của từng nhóm năm số, rồi tìm hiệu của hai giá trị trung bình.",
    "q.7.4-08.q": "Từ kết quả trên (mỗi nhóm 5 lá), người nông dân kết luận: “Cỏ cạnh phân bò luôn mọc dài hơn.” Nhận xét nào tốt nhất?",
    "q.7.4-08.choices": ["Kết quả ủng hộ ý đó, nhưng 5 lá ở một chỗ là mẫu quá nhỏ để nói “luôn luôn”","Kết luận đã được chứng minh, vì lá nào cạnh phân cũng dài hơn mọi lá ở xa phân","Kết quả không cho thấy gì, vì trung bình của hai nhóm bằng nhau","Bà chỉ nên đo lá dài nhất ở mỗi chỗ để thí nghiệm công bằng"],
    "q.7.4-09.q": "Một số vi khuẩn biến sữa thành sữa chua bằng cách chuyển đường trong sữa thành acid. pH của sữa thay đổi thế nào khi thành sữa chua?",
    "q.7.4-09.choices": ["Giảm xuống, vì acid được tạo ra","Tăng lên, vì acid được tạo ra","Không đổi, vì vi khuẩn không làm đổi pH"],
    "q.7.4-10.q": "Một loại thuốc diệt côn trùng không bị phân hủy trong cơ thể động vật. Chuỗi thức ăn: cây thủy sinh → côn trùng → cá nhỏ → cá lớn → đại bàng cá. Con vật nào nhiều khả năng tích lũy nhiều thuốc nhất trong cơ thể?",
    "q.7.4-10.choices": ["Đại bàng cá","Côn trùng","Cá nhỏ","Tất cả có lượng như nhau"]
  }
});
